using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysPayableTotal95()
    {
        var checkoutTypes = typeof(ApplicationMarker).Assembly.GetExportedTypes()
            .Where(type => type.Name.Contains("Checkout", StringComparison.OrdinalIgnoreCase))
            .ToArray();

        Assert.True(checkoutTypes.Length > 0, "No checkout pricing capability exists, so Gold 100.00 -> 95.00 cannot be produced.");
    }
}
